mapper.select:
SELECT nvl(SUM(LCC.CREDIT_UNEXPOSURE_AMT),0)-nvl(SUM(CRE.DUE_AMOUNT),0) AMOUNT FROM LON_CREDIT_CONTRACT_CALC LCC LEFT JOIN ( SELECT LCCL.CREDIT_CONTRACT_ID, nvl(SUM(ROUND((LCW.DUE_AMOUNT*nvl(LCW.EXCHANGE_RATE,1)),2)) ,0) DUE_AMOUNT FROM LON_CONTRACT LC JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.CONTRACT_ID=LC.CONTRACT_ID JOIN LON_CREDIT_CONTRACT_LINE LCCL ON LCCL.CREDIT_LINE_ID=LC.CREDIT_LINE_ID WHERE LC.RELE_CREDIT_FLAG='Y' AND LCW.WITHDRAW_STATUS!='APPROVED' AND LCW.WITHDRAW_STATUS!='PENDING' AND LCW.DATA_CLASS='NORMAL' GROUP BY LCCL.CREDIT_CONTRACT_ID) CRE ON CRE.CREDIT_CONTRACT_ID=LCC.CREDIT_CONTRACT_ID WHERE 1=1
AND LCC.CREDIT_CONTRACT_ID= ( SELECT LCCL.CREDIT_CONTRACT_ID FROM LON_CREDIT_CONTRACT_LINE LCCL WHERE LCCL.CREDIT_LINE_ID=#{creditLineId} )
AND LCC.CREDIT_CONTRACT_ID=#{creditContractId}

SELECT nvl(SUM(ROUND((LCW.DUE_AMOUNT*nvl(LCW.EXCHANGE_RATE,1)),2)) ,0) DUE_AMOUNT FROM LON_CONTRACT LC JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.CONTRACT_ID=LC.CONTRACT_ID JOIN LON_CREDIT_CONTRACT_LINE LCCL ON LCCL.CREDIT_LINE_ID=LC.CREDIT_LINE_ID WHERE LC.RELE_CREDIT_FLAG='Y' AND LCW.WITHDRAW_STATUS!='APPROVED' AND LCW.WITHDRAW_STATUS!='PENDING' AND LCW.DATA_CLASS='NORMAL'
AND LC.CREDIT_LINE_ID=#{creditLineId}
AND LCCL.CREDIT_CONTRACT_ID=#{creditContractId}

SELECT COUNT(1) FROM LON_CREDIT_CONTRACT LCC JOIN LON_CREDIT_CONTRACT_LINE LCCL ON LCC.CREDIT_CONTRACT_ID=LCCL.CREDIT_CONTRACT_ID JOIN LON_CONTRACT LC ON LCCL.CREDIT_LINE_ID=LC.CREDIT_LINE_ID AND LC.RELE_CREDIT_FLAG='Y'
JOIN LON_CONTRACT_WITHDRAW LCW ON LCW.CONTRACT_ID=LC.CONTRACT_ID AND LCW.DATA_CLASS='NORMAL'
WHERE 1=1
AND LCC.CREDIT_CONTRACT_ID=#{creditContractId}
AND LCCL.CREDIT_LINE_ID =#{creditLineId}

( SELECT LCCL.CREDIT_CATEGORY, LCCL.WITHDRAW_DEADLINE, LCCL.BUSINESS_DEADLINE, LCCL.CREDIT_CONTRACT_LINE_ID, LCCL.CREDIT_CONTRACT_ID, LCCL.RATE, LCCL.GUARANTEE_TYPE, LCCL.DESCRIPTION, LCCL.CREDIT_LINE_ID, LCCL.CREDIT_TERM, HCL.DOCUMENT_TYPE, HCL.CREDIT_LINE_AMT, CLC.CREDIT_EXPOSURE_AMT, nvl(CLC.WITHDRAW_BALANCE,0) WITHDRAW_BALANCE, nvl(HCL.CREDIT_LINE_AMT,0)- nvl(CLC.CREDIT_EXPOSURE_AMT,0) CREDIT_AVAILABLE_AMT, nvl(CLC.TOTAL_WITHDRAW_AMOUNT,0) TOTAL_WITHDRAW_AMOUNT, nvl(CLC.LIMIT_WITHDRAW_AMOUNT,0) LIMIT_WITHDRAW_AMOUNT, HCL.VALID_FROM, HCL.VALID_TO, HCL.CANCEL_FLAG, HCL.SOURCE_CREDIT_LINE_ID, nvl( ( SELECT COUNT(1) FROM LON_CONTRACT LC JOIN LON_CONTRACT_WITHDRAW LCW ON LC.CONTRACT_ID=LCW.CONTRACT_ID WHERE LC.RELE_CREDIT_FLAG='Y' AND LCW.DATA_CLASS='NORMAL' AND LC.CREDIT_LINE_ID=LCCL.CREDIT_LINE_ID),0) WITHDRAW_COUNT, 'N' SOURCE_CREDIT_FLAG, v1.meaning credit_category_n, v2.meaning guarantee_type_n, hdt.description document_type_n FROM LON_CREDIT_CONTRACT_LINE LCCL JOIN HLS_CREDIT_LINE HCL ON HCL.CREDIT_LINE_ID= LCCL.CREDIT_LINE_ID JOIN LON_CREDIT_LINE_CALC CLC ON CLC.CREDIT_LINE_ID=HCL.CREDIT_LINE_ID left join sys_code_value_b_v v1 on v1.code= 'LON.CREDIT_CATEGORY' and v1.code_value = LCCL.CREDIT_CATEGORY left join sys_code_value_b_v v2 on v2.code= 'LON.GUARANTEE_TYPE' and v2.code_value = LCCL.GUARANTEE_TYPE left join hls_document_type hdt on hdt.document_category = 'HLS_CREDIT_LINE' and hdt.business_type = 'FINANCING_LOAN' and hdt.enabled_flag = 'Y' and hdt.document_type = HCL.DOCUMENT_TYPE WHERE 1=1
AND LCCL.CREDIT_CONTRACT_ID=#{creditContractId}
AND LCCL.CREDIT_CONTRACT_ID=-1
) UNION ( SELECT LCCL.CREDIT_CATEGORY, LCCL.WITHDRAW_DEADLINE, LCCL.BUSINESS_DEADLINE, LCCL.CREDIT_CONTRACT_LINE_ID, LCCL.CREDIT_CONTRACT_ID, LCCL.RATE, LCCL.GUARANTEE_TYPE, LCCL.DESCRIPTION, LCCL.CREDIT_LINE_ID, LCCL.CREDIT_TERM, HCL.DOCUMENT_TYPE, HCL.CREDIT_LINE_AMT, CLC.CREDIT_EXPOSURE_AMT, nvl(CLC.WITHDRAW_BALANCE,0) WITHDRAW_BALANCE, nvl(HCL.CREDIT_LINE_AMT,0)- nvl(CLC.CREDIT_EXPOSURE_AMT,0) CREDIT_AVAILABLE_AMT, nvl(CLC.TOTAL_WITHDRAW_AMOUNT,0) TOTAL_WITHDRAW_AMOUNT, nvl(CLC.LIMIT_WITHDRAW_AMOUNT,0) LIMIT_WITHDRAW_AMOUNT, HCL.VALID_FROM, HCL.VALID_TO, HCL.CANCEL_FLAG, HCL.SOURCE_CREDIT_LINE_ID, nvl( ( SELECT COUNT(1) FROM LON_CONTRACT LC JOIN LON_CONTRACT_WITHDRAW LCW ON LC.CONTRACT_ID=LCW.CONTRACT_ID WHERE LC.RELE_CREDIT_FLAG='Y' AND LCW.DATA_CLASS='NORMAL' AND LC.CREDIT_LINE_ID=LCCL.CREDIT_LINE_ID),0) WITHDRAW_COUNT, 'Y' SOURCE_CREDIT_FLAG,
v1.meaning credit_category_n, v2.meaning guarantee_type_n, hdt.description document_type_n FROM LON_CREDIT_CONTRACT_LINE LCCL JOIN HLS_CREDIT_LINE HCL ON HCL.CREDIT_LINE_ID= LCCL.CREDIT_LINE_ID JOIN LON_CREDIT_CONTRACT_CALC LCC ON LCC.CREDIT_CONTRACT_ID= LCCL.CREDIT_CONTRACT_ID JOIN LON_CREDIT_LINE_CALC CLC ON CLC.CREDIT_LINE_ID=LCCL.CREDIT_LINE_ID
left join sys_code_value_b_v v1 on v1.code= 'LON.CREDIT_CATEGORY' and v1.code_value = LCCL.CREDIT_CATEGORY left join sys_code_value_b_v v2 on v2.code= 'LON.GUARANTEE_TYPE' and v2.code_value = LCCL.GUARANTEE_TYPE left join hls_document_type hdt on hdt.document_category = 'HLS_CREDIT_LINE' and hdt.business_type = 'FINANCING_LOAN' and hdt.enabled_flag = 'Y' and hdt.document_type = HCL.DOCUMENT_TYPE WHERE LCCL.CREDIT_CONTRACT_ID= nvl(( SELECT MAX(C.CREDIT_CONTRACT_ID) FROM LON_CREDIT_CONTRACT C WHERE C.CREDIT_BP_ID=#{creditBpId} AND C.company_id =#{request.companyId}
AND C.CREDIT_CONTRACT_ID!=#{creditContractId}
),0) AND ( HCL.CANCEL_FLAG='N' OR HCL.CANCEL_FLAG IS NULL) AND ( nvl(CLC.WITHDRAW_BALANCE,0)>0 OR nvl(LCC.ACTUAL_AVAILABLE_AMT,0)>0) )
